$src=Get-Content "$PSScriptRoot\MD-Browser.ps1" -Raw;$r='$win.Add_Closing({"CLOSING"|Out-Host});$x=$win.ShowDialog();"RESULT=$x"';$tmp="$PSScriptRoot\_close-harness.ps1";Set-Content $tmp ($src.Replace('$win.ShowDialog() | Out-Null',$r));$root=Join-Path $env:TEMP 'md-browser-close';Remove-Item $root -Recurse -Force -EA SilentlyContinue;New-Item $root -ItemType Directory|Out-Null;Set-Content "$root\first.md" '# First';powershell -STA -NoProfile -File $tmp -Path $root;Remove-Item $tmp -Force;Remove-Item $root -Recurse -Force